# FNV-1a hash implementation to verify and brute force
# The hash must equal 0xcfb2ee18

def fnv1a_hash(data):
    """FNV-1a hash for bytes"""
    h = 0x811c9dc5
    for byte in data:
        h ^= byte
        h = (h * 0x1000193) & 0xffffffff
    return h

# First, let's verify the decoy string "0eaccfc8"
decoy_content = b"0eaccfc8"
print(f"Hash of '0eaccfc8': {hex(fnv1a_hash(decoy_content))}")
print(f"Target hash: 0xcfb2ee18")

