# Let's try a brute force approach for short strings
import itertools
import string

# Try all printable characters for short lengths
chars = string.ascii_lowercase + string.digits + string.ascii_uppercase

def search_preimage(target_hash, max_len=8):
    for length in range(1, max_len + 1):
        print(f"Searching length {length}...")
        for combo in itertools.product(chars, repeat=length):
            candidate = ''.join(combo).encode()
            if fnv1a_hash(candidate) == target_hash:
                return candidate.decode()
    return None

# Try short searches first
result = search_preimage(0xcfb2ee18, 4)
if result:
    print(f"Found: FLAG{{{result}}}")
else:
    print("Not found in length 1-4")

